//! Mission data (PLAN Architecture #3/#6: data-driven missions, modes as
//! rulesets over rosters). One RON per map+era under engine/missions/,
//! GENERATED by `scripts/gen_missions.py` from the PS2 mission bytecode with
//! the PC mod-tools .lua of the same name as the readable referee (audit A6,
//! analysis/a6-mission-lua.md; ticket/spawn semantics in
//! analysis/re-tickets-spawn.md §1.5–1.6, §2.7). `<key>_con.ron` is the
//! galactic-civil-war era and `<key>_con_cw.ron` the clone-wars one; maps
//! that ship only one era have only `<key>_con.ron`. [`pick`] is which of a
//! map's missions a battle of two armies runs and the team the player's army
//! has in it (card ERAM): the mission whose own pair was picked, else the
//! default one as a cross-era battle.
//!
//! Not yet consumed: `spawn_delay`/`spawn_interval` — the wave scheme IS
//! implemented (core::sim::SpawnWaves) but seeded from
//! SpawnWaves::mission_default() (10 s / 0.25 s) rather than from here and the member pool beyond the
//! alive cap (units initially spawned = min(units, ai_alive_cap)). The
//! `attacking_team` field is also carried as data. `cps` and `death_regions` are applied
//! (`layout::apply_mission`, `main/battle.rs`'s walk setup), `voice` is the
//! commander's lines (`crate::announce`), `era` selects the mission-specific
//! minimap orientation, `ai` is the bots' settings ([`MissionDef::apply_ai`],
//! card MAIS), and `source` is printed by the sweep. The Ewok and Wookiee
//! rosters and their directed relations are installed by [`crate::native_teams`].

use anyhow::{Context, Result};
use serde::Deserialize;
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, Deserialize)]
pub struct TeamDef {
    /// Faction key (all|imp|rep|cis).
    pub faction: String,
    /// SetUnitCount / SetupTeams units (member pool, incl. the human).
    pub units: u32,
    /// SetReinforcementCount.
    pub tickets: u32,
    /// The team's class MIX, in the order the mission script names it — BF1
    /// `AddUnitClass(team, class, count)` in call order, BF2 `SetupTeams`
    /// slot-table order (soldier, assault, engineer, sniper, officer,
    /// special). `(class, min, max)`: the counts are MINIMUMS and do not sum
    /// to `units` (analysis/re-tickets-spawn.md §1.5–1.6), and only BF2
    /// authors a per-class maximum. Defaulted so a RON written before the
    /// generator emitted it still parses.
    #[serde(default)]
    pub classes: Vec<(String, u32, Option<u32>)>,
}

/// One BF2 SIDE resource request, with its source file and native load order.
#[derive(Debug, Clone, Deserialize, PartialEq, Eq)]
pub struct SideClassLoad {
    /// Original-case SIDE filename stem, excluding `.lvl`.
    pub side: String,
    /// Original request spelling; it may name a resource alias, not a class.
    pub request: String,
}

/// A native team outside the two main armies. Its reinforcements are unlimited
/// (analysis/re-tickets-spawn.md §2.1).
#[derive(Debug, Clone, Deserialize, PartialEq, Eq)]
pub struct LocalTeamDef {
    /// Authored Lua team number (3 or higher).
    pub team: u8,
    /// SetUnitCount, the team's member pool.
    pub units: u32,
    /// Authored class rows in script order, in the same format as TeamDef.
    pub classes: Vec<(String, u32, Option<u32>)>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct MissionDef {
    pub map: String,
    pub mode: String,
    pub source_game: String,
    /// `SetHeroClass(team, class)` from the BF2 PS2 mission (Lua team numbers).
    #[serde(default)]
    pub heroes: Vec<(u8, String)>,
    /// Every BF2 `ReadDataFile("SIDE\\...", ...)` resource request with its
    /// source side file, in call/argument order, including repeats and aliases.
    /// Native shared animation definitions use the first loaded definition;
    /// this is independent of team/roster order. Older missions default empty.
    #[serde(default)]
    pub class_load_order: Vec<SideClassLoad>,
    pub teams: Vec<TeamDef>,
    /// Alive-AI cap per team. BF2 conquest: the NumBots default, 16. BF1:
    /// there is no cap below the member pool, so this is the larger of the
    /// two unit counts and `initial_ai` clamps each team to its own pool.
    pub ai_alive_cap: u32,
    pub spawn_delay: f32,
    pub spawn_interval: f32,

    // --- Extracted 2026-09-01 from the mission Lua. `cps` and
    // `death_regions` are applied (`layout::apply_mission`); `era` selects
    // minimap orientation. All default so that any RON written before they
    // existed still parses.
    /// `"cw"` | `"gcw"` — which era's mission script this came from.
    #[serde(default)]
    pub era: Option<String>,
    /// `SetAttackingTeam(t)`, 1-based; None when the mission never calls it.
    #[serde(default)]
    pub attacking_team: Option<u8>,
    /// Per-command-post initial ownership the MISSION assigns, 1-based team
    /// (0 = neutral). Only the posts the script itself re-authors appear —
    /// everything else keeps the ownership baked into the world layer. Two
    /// mechanisms in the corpus: `SetProperty("cp1", "Team", "1")` (BF2
    /// Kamino) and `SetObjectTeam("CP3", 1)` (BF2 Hoth). No BF1 mission
    /// script assigns command-post ownership at all.
    #[serde(default)]
    pub cps: Vec<(String, u8)>,
    /// `AddDeathRegion("name")` region names, in call order.
    #[serde(default)]
    pub death_regions: Vec<String>,
    /// `SetMaxPlayerFlyHeight(y)`, the last call: the soldiers' fly-height
    /// ceiling (card JETP, `analysis/re-jetpack.md` §5.3; BF2's rule on
    /// every map, so a BF1 script's `SetMaxFlyHeight` - the AI flyers' - is
    /// not the soldiers'). None = the engine's 200
    /// (`core::soldier::DEFAULT_FLY_CEILING`). A RON generated before this
    /// field (`scripts/gen_missions.py`) has none.
    #[serde(default)]
    pub max_player_fly_height: Option<f32>,
    /// `SetMinPlayerFlyHeight(y)` (a human flyer's floor); None = -200.
    #[serde(default)]
    pub min_player_fly_height: Option<f32>,
    /// `SetMaxFlyHeight(y)` / `SetMinFlyHeight(y)`, the AI flyers' band
    /// (BF1 `DAT_005873b0` / `DAT_005873ac`); None = 200 / -200.
    #[serde(default)]
    pub max_fly_height: Option<f32>,
    #[serde(default)]
    pub min_fly_height: Option<f32>,
    /// BF2 `SetGroundFlyerMap(1)`: halves the AI follower's roll wobble.
    #[serde(default)]
    pub ground_flyer_map: bool,
    /// `AddLandingRegion(name)`: where a flyer may land, slows, and holds its fire
    /// (`analysis/re-flyer.md`). Only the space scripts call it.
    #[serde(default)]
    pub landing_regions: Vec<String>,
    #[serde(default)]
    pub space_assault: Option<SpaceAssaultDef>,
    /// The conquest command-post roster, in `CommandPost:New` order — the
    /// posts the mission actually hands to its `ObjectiveConquest`, which is
    /// NOT every post in the world layer (BF2 Hoth builds four and kills the
    /// fifth). Empty on every BF1 mission: BF1 inlines conquest and hands
    /// nothing to an objective object, so its roster is whatever the world
    /// layer contains.
    #[serde(default)]
    pub posts: Vec<String>,
    /// Every `KillObject("name")` target, in call order — command posts the
    /// mission removes (BF2 Hoth `CP7`, Death Star `CP6`) and props it opens
    /// (Tantive `blastdoor`, Yavin `TempleBlastDoor`).
    #[serde(default)]
    pub killed: Vec<String>,
    /// Legacy first-class summary and member pool. It cannot identify the team
    /// or describe the complete roster. New consumers should use `local_teams`.
    #[serde(default)]
    pub locals: Option<(String, u32)>,
    /// Authored native teams. Older RON files may carry a legacy `locals`
    /// summary, which omits team IDs and classes.
    #[serde(default)]
    pub local_teams: Vec<LocalTeamDef>,
    /// Authored `SetTeamAsFriend` / `SetTeamAsEnemy` calls involving local teams,
    /// in script order. Each row is (source Lua team, target Lua team, friendly).
    /// Each call sets one direction.
    #[serde(default)]
    pub local_team_relations: Vec<(u8, u8, bool)>,
    /// `ScriptPostLoad`'s `BlockPlanningGraphArcs` (`true`) /
    /// `UnblockPlanningGraphArcs` (`false`) calls, in order, including those
    /// it makes through the script's own functions — the `plnp` groups the
    /// mission closes before the first tick (`core::route_patch`). BF2 only:
    /// DEA1 `compactor`, KAS2 the gate and the three wooden walls, TAN1
    /// `turbine`. Applied unless `OPENBF_PLNP_MISSION=0`
    /// ([`MissionDef::apply_arc_blocks`]); the events that later UNBLOCK them
    /// (a gate or wall destroyed, a bridge extended) are not modelled — the
    /// port destroys nothing, so its barriers and their blocks both stand for
    /// the whole round (queue DR3B).
    #[serde(default)]
    pub arc_blocks: Vec<(String, bool)>,
    /// Startup IsLocked writes, in mission call order.
    #[serde(default)]
    pub door_locks: Vec<(String, bool)>,
    /// `ScriptPostLoad`'s `EnableBarriers` (`true`) / `DisableBarriers`
    /// (`false`) calls, in order (card BNDS). Every `BARR` barrier loads
    /// enabled; these are the ones the mission opens before the first tick —
    /// the doors' (BF2 KAM1's `FRONTDOOR*`), which a bot has to walk through
    /// now that the steering takes a barrier as a wall. BF2 only (no BF1
    /// script calls either). Applied by [`MissionDef::apply_barriers`]; the
    /// calls a mission makes LATER (a gate destroyed, a shield dropped) are
    /// not modelled, like the arc blocks'.
    #[serde(default)]
    pub barriers: Vec<(String, bool)>,
    /// `ScriptPostLoad`'s `OnCharacterDeathTeam(handler, t)` whose handler is
    /// a bare `AddReinforcements(team, -n)`: a death on port team `on` also
    /// costs port team `team` `tickets` (Lua team − 1), on top of the
    /// objective's own one ([`MissionDef::apply_death_drains`]). BF2 Death
    /// Star only (analysis/re-time-limit.md §6 [V][O]; queue DSD).
    #[serde(default)]
    pub death_drains: Vec<DeathDrain>,
    /// The commander's lines the script sets (card ANNC,
    /// analysis/re-announcer.md §2.2-2.4), consumed by `crate::announce`.
    /// Absent on a mission whose script sets none.
    #[serde(default)]
    pub voice: VoiceDef,
    /// The script's music setters (card AMBM,
    /// analysis/re-ambience-music.md 3.1), consumed by `crate::music`.
    #[serde(default)]
    pub music: MusicCalls,
    /// The sound sub-levels the script loads, in call order (card SNDE):
    /// `ReadDataFile("sound\\kas.lvl;kas2gcw")` is `("kas", "kas2gcw")`. The
    /// PS2 holds these and no other of the planet's LVL, so a sound's
    /// definition is theirs (`crate::sounds::SoundLib::find`). One per
    /// script on both discs.
    #[serde(default)]
    pub sound: Vec<(String, String)>,
    #[serde(default)]
    pub birds: Vec<(f32, String)>,
    /// The spawn screens' backdrops (card SSELB, re-spawn-flow §1.1):
    /// `AddCameraShot(qw, qx, qy, qz, x, y, z)` in call order, the first 16
    /// (the PS2's cap, B2:31916). Every mission script on both discs calls
    /// it; [`MissionDef::camera_shots`] reads them.
    #[serde(default, rename = "camera_shots")]
    pub camera_shot_calls: Vec<[f32; 7]>,
    /// Card MAIS: the AI settings the script sets as it starts
    /// ([`AiSettings`]), applied by [`MissionDef::apply_ai`]. Absent on a
    /// mission whose script sets none.
    #[serde(default)]
    pub ai: AiSettings,
    /// The PC .lua and PS2 script this record was read out of.
    #[serde(default)]
    pub source: String,
}

/// [`MissionDef::music`]: the three music setters' calls, in the script's
/// order and with its own (Lua, 1-based) team numbers.
#[derive(Debug, Clone, Default, PartialEq, Deserialize)]
pub struct MusicCalls {
    /// `SetAmbientMusic(team, x, Music, state, flag)`: state 0 start, 1
    /// middle, 2 end; with `flag` the threshold is `x` times the team's
    /// reinforcements at the call.
    #[serde(default)]
    pub ambient: Vec<(u8, f32, String, u8, bool)>,
    /// `SetVictoryMusic(team, Music)`.
    #[serde(default)]
    pub victory: Vec<(u8, String)>,
    /// `SetDefeatMusic(team, Music)`.
    #[serde(default)]
    pub defeat: Vec<(u8, String)>,
}

/// [`MissionDef::voice`]: the three voice-over setters' calls, in the
/// script's order and with its own (Lua, 1-based) team numbers — which side is
/// team 1 differs per script.
#[derive(Debug, Clone, Default, PartialEq, Deserialize)]
pub struct VoiceDef {
    /// `SetBleedingVoiceOver(listener, team, line, flag)`.
    #[serde(default)]
    pub bleeding: Vec<(u8, u8, String, bool)>,
    /// `SetLowReinforcementsVoiceOver(listener, team, line, x, flag)`: the
    /// line is due at `x` × the listener team's tickets when `flag` is set.
    /// No BF1 Clone Wars script calls it.
    #[serde(default)]
    pub low_reinforcements: Vec<(u8, u8, String, f32, bool)>,
    /// `SetOutOfBoundsVoiceOver(team, line)`: said to a team's player when his
    /// droid leaves the boundary (`Commander::leaving`); soldiers and vehicles are
    /// card BNDY.
    #[serde(default)]
    pub out_of_bounds: Vec<(u8, String)>,
}

/// [`MissionDef::ai`]: the script's AI knobs (card MAIS;
/// `analysis/re-ai-difficulty.md` 3), with its own (Lua, 1-based) team
/// numbers. `None` / empty: the script does not set it, and the engine's
/// default holds ([`core::sim::MissionAi`]).
#[derive(Debug, Clone, Default, PartialEq, Deserialize)]
pub struct AiSettings {
    /// `SetAIViewMultiplier(m)`.
    #[serde(default)]
    pub view_mult: Option<f32>,
    /// `SetTeamAggressiveness(team, v)`, the last call per team.
    #[serde(default)]
    pub aggressiveness: Vec<(u8, f32)>,
    /// `AISnipeSuitabilityDist(d)`, m.
    #[serde(default)]
    pub snipe_suitability: Option<f32>,
    /// `AICanCaptureCP(post, team, false)` still in force once the script's
    /// start has run: (post, team).
    #[serde(default)]
    pub no_capture: Vec<(String, u8)>,
}

#[derive(Debug, Clone, Default, Deserialize)]
pub struct SpaceAssaultDef {
    pub critical: Vec<(String, String, u32)>,
    pub shields: Vec<SpaceShieldsDef>,
    pub destroyables: Vec<Vec<Vec<String>>>,
    pub turrets: Vec<SpaceTurretsDef>,
    pub frigate_turrets: Vec<(String, Vec<String>)>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct SpaceShieldsDef {
    pub objects: Vec<String>,
    pub max: f32,
    pub add: f32,
    pub controller: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct SpaceTurretsDef {
    pub team: u8,
    pub mainframe: String,
    pub turrets: Vec<String>,
}

/// One [`MissionDef::death_drains`] entry, port (0-based) teams.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
pub struct DeathDrain {
    pub on: u8,
    pub team: u8,
    pub tickets: u32,
}

/// The mission a battle of `map` in `mode` runs for the two armies picked,
/// and the team the first army (the player's) sits on in it (card ERAM).
#[derive(Debug, Clone)]
pub struct Pick {
    pub path: PathBuf,
    pub mission: MissionDef,
    /// The sim team of the player's army: its own team in the mission when
    /// the pair is the mission's own, else 0. Where the battle runs the spawn
    /// screens (card SSELA) this only orders the armies and seats the held
    /// player; the side the player accepts there is the team it plays.
    pub player_team: u8,
    /// The pair picked is this mission's own pair (either order).
    pub own: bool,
}

/// The era suffixes a map's missions come in (module header): the default
/// (`<key>_<mode>.ron`) first.
const ERA_SUFFIXES: [&str; 2] = ["", "_cw"];

/// Which of a map's missions (their faction pairs, the default first) runs
/// for `armies`, and the player's team in it: the mission whose pair is
/// exactly the armies picked, in either order, with `armies[0]` on its own
/// team there; else the default mission with the armies as picked (a
/// cross-era battle; the player on team 0).
pub fn pick_index(missions: &[[String; 2]], armies: [&str; 2]) -> Option<(usize, u8, bool)> {
    if armies[0] != armies[1] {
        for (i, f) in missions.iter().enumerate() {
            if f[0] == armies[0] && f[1] == armies[1] {
                return Some((i, 0, true));
            }
            if f[1] == armies[0] && f[0] == armies[1] {
                return Some((i, 1, true));
            }
        }
    }
    (!missions.is_empty()).then_some((0, 0, false))
}

/// The faction pairs of `map`'s mission files for `mode` in `dir` (each era
/// suffix); the Instant Action screen's runnable check (`ui::shell`).
pub fn pairs(dir: &Path, map: &str, mode: &str) -> Vec<[String; 2]> {
    ERA_SUFFIXES
        .iter()
        .map(|s| dir.join(format!("{map}_{mode}{s}.ron")))
        .filter(|p| pak::is_file(p))
        .filter_map(|p| MissionDef::load(&p).ok())
        .map(|m| m.factions())
        .collect()
}

/// [`pick_index`] over the mission files of `map` in `dir`. `None` when the
/// map has no mission file for `mode`.
pub fn pick(dir: &Path, map: &str, mode: &str, armies: [&str; 2]) -> Option<Pick> {
    let mut found: Vec<(PathBuf, MissionDef)> = ERA_SUFFIXES
        .iter()
        .filter_map(|s| {
            let path = dir.join(format!("{map}_{mode}{s}.ron"));
            // Most era suffixes have no file; one that exists and fails to
            // load is a broken mission, and is said (a Windows bake once wrote
            // them in cp1252 and every battle ran without its mission).
            match MissionDef::load(&path) {
                Ok(m) => Some((path, m)),
                Err(e) => {
                    if pak::is_file(&path) {
                        eprintln!("mission: {e:#}");
                    }
                    None
                }
            }
        })
        .collect();
    let pairs: Vec<[String; 2]> = found.iter().map(|(_, m)| m.factions()).collect();
    let (i, player_team, own) = pick_index(&pairs, armies)?;
    let (path, mission) = found.swap_remove(i);
    Some(Pick {
        path,
        mission,
        player_team,
        own,
    })
}

impl MissionDef {
    /// The mission's camera shots (the spawn screens' level-start views).
    pub fn camera_shots(&self) -> Vec<crate::spawn_backdrop::CameraShot> {
        self.camera_shot_calls
            .iter()
            .map(|&a| crate::spawn_backdrop::CameraShot::from_call(a))
            .collect()
    }

    pub fn load(path: &Path) -> Result<MissionDef> {
        let txt = pak::read_to_string(path).with_context(|| path.display().to_string())?;
        let m: MissionDef =
            ron::from_str(&txt).with_context(|| format!("parse {}", path.display()))?;
        if m.teams.len() != 2 {
            anyhow::bail!("{}: v0 missions need exactly two teams", path.display());
        }
        // A team with no reinforcements can never spawn anyone, and the first
        // spawn is what builds the player — so zero tickets crashed at
        // startup rather than starting a round nobody could play. Reject it
        // where the value enters instead of teaching the sim to limp.
        if let Some(t) = m.teams.iter().find(|t| t.tickets == 0) {
            anyhow::bail!(
                "{}: team '{}' has 0 reinforcements — a round with no tickets \
                 cannot spawn anyone",
                path.display(),
                t.faction
            );
        }
        Ok(m)
    }

    /// Apply startup lock overrides to the doors that exist in this mode layer.
    pub fn apply_door_locks(&self, doors: &mut [core::door::Door], manifest: &manifest::Manifest) {
        for (name, locked) in &self.door_locks {
            for door in doors.iter_mut() {
                if manifest.instances[door.instance]
                    .name
                    .eq_ignore_ascii_case(name)
                {
                    door.locked = *locked;
                }
            }
        }
    }

    /// Replay [`MissionDef::arc_blocks`] onto the map's planning graph unless
    /// `OPENBF_PLNP_MISSION=0`; returns the blocked-group mask it leaves (0
    /// when the flag is off, the map ships no `plnp`, or no call names one of
    /// its groups). ON by default since DR3B, as `ScriptPostLoad` does on the
    /// PS2; `=0` gives the authored all-open table, byte for byte DR3's
    /// default (and DR2's sweep).
    pub fn apply_arc_blocks(&self, nav: Option<&mut core::nav::NavGraph>) -> u32 {
        if std::env::var("OPENBF_PLNP_MISSION").as_deref() == Ok("0") {
            return 0;
        }
        self.replay_arc_blocks(nav)
    }

    /// [`MissionDef::apply_arc_blocks`] without the flag test.
    pub fn replay_arc_blocks(&self, nav: Option<&mut core::nav::NavGraph>) -> u32 {
        let Some(nav) = nav else { return 0 };
        for (name, block) in &self.arc_blocks {
            nav.block_arcs(&[crate::classdb::fnv1a_lowercase(name)], *block);
        }
        nav.blocked_groups()
    }

    /// Replay [`MissionDef::barriers`] onto the map's planning graph; returns
    /// how many barriers a call switched (a name the graph does not carry
    /// switches none).
    pub fn apply_barriers(&self, nav: Option<&mut core::nav::NavGraph>) -> usize {
        let Some(nav) = nav else { return 0 };
        self.barriers
            .iter()
            .map(|(name, on)| nav.set_barriers(crate::classdb::fnv1a_lowercase(name), *on))
            .sum()
    }

    /// Load [`MissionDef::death_drains`] into the battle's
    /// [`core::battle::Battle::death_drain`] table (teams past 1 ignored).
    pub fn apply_death_drains(&self, battle: &mut core::battle::Battle) {
        for d in &self.death_drains {
            if d.on < 2 && d.team < 2 {
                battle.death_drain[usize::from(d.on)][usize::from(d.team)] += d.tickets;
            }
        }
    }

    /// Card MAIS: put [`MissionDef::ai`] into the sim (Lua team `t` is port
    /// team `t - 1`). Run once the posts are in (`WalkSim::add_posts`): a
    /// capture ban names its post. Answers the bans that found their post.
    pub fn apply_ai(&self, sim: &mut core::sim::Sim) -> usize {
        // Canonical stock-script policy, shared by every source profile;
        // retained mission files predate this setting. See re-jetpack §17.
        let mut ai = core::sim::MissionAi {
            allow_blind_jet_jumps: !matches!(self.map.as_str(), "bf1_kam1" | "bf2_kam1"),
            ..Default::default()
        };
        if let Some(m) = self.ai.view_mult {
            ai.set_view_mult(m);
        }
        for &(t, v) in &self.ai.aggressiveness {
            if let Some(a) = ai.aggressiveness.get_mut(usize::from(t.wrapping_sub(1))) {
                *a = v;
            }
        }
        if let Some(d) = self.ai.snipe_suitability {
            ai.set_snipe_suitability(d);
        }
        sim.mission_ai = ai;
        let mut found = 0;
        for (name, t) in &self.ai.no_capture {
            let team = t.wrapping_sub(1);
            for cp in sim.cps.iter_mut() {
                if team < 8 && cp.def.name.eq_ignore_ascii_case(name) {
                    cp.ai_capture_ban |= 1 << team;
                    found += 1;
                }
            }
        }
        found
    }

    /// [`MissionDef::sound`]'s sub-level names.
    pub fn sound_levels(&self) -> Vec<String> {
        self.sound.iter().map(|(_, sub)| sub.clone()).collect()
    }

    pub fn factions(&self) -> [String; 2] {
        [self.teams[0].faction.clone(), self.teams[1].faction.clone()]
    }

    pub fn is_hero_assault(&self) -> bool {
        self.mode == "eli"
    }

    pub fn tickets(&self) -> [u32; 2] {
        [self.teams[0].tickets, self.teams[1].tickets]
    }

    /// AI to field initially per team: the pool minus the human slot on the
    /// player's team, capped by the alive-AI cap.
    pub fn initial_ai(&self, team: usize, has_player: bool) -> u32 {
        let pool = self.teams[team].units.saturating_sub(u32::from(has_player));
        pool.min(self.ai_alive_cap)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn missions_dir() -> &'static Path {
        Path::new(concat!(env!("CARGO_MANIFEST_DIR"), "/../../missions"))
    }

    /// A public checkout has no missions until `scripts/pack.py` generates
    /// them from the player's discs: the tests that read them skip.
    fn no_missions() -> bool {
        let none = !std::fs::read_dir(missions_dir()).is_ok_and(|mut d| {
            d.any(|e| e.is_ok_and(|e| e.path().extension().is_some_and(|x| x == "ron")))
        });
        if none {
            eprintln!("SKIP: no engine/missions/*.ron (scripts/pack.py generates them)");
        }
        none
    }

    #[test]
    fn class_load_order_preserves_names_repeats_and_legacy_default() {
        let legacy = r#"(map: "x", mode: "con", source_game: "bf2", teams: [
            (faction: "rep", units: 20, tickets: 150),
            (faction: "cis", units: 20, tickets: 150)],
            ai_alive_cap: 16, spawn_delay: 10.0, spawn_interval: 0.25)"#;
        let old: MissionDef = ron::from_str(legacy).unwrap();
        assert!(old.class_load_order.is_empty());
        let ordered = legacy.replacen(
            "teams:",
            r#"class_load_order: [(side: "REP", request: "rep_HERO_aalya"),
                (side: "ewk", request: "bank_alias"),
                (side: "REP", request: "rep_HERO_aalya")], teams:"#,
            1,
        );
        let loaded: MissionDef = ron::from_str(&ordered).unwrap();
        assert_eq!(
            loaded
                .class_load_order
                .iter()
                .map(|load| (load.side.as_str(), load.request.as_str()))
                .collect::<Vec<_>>(),
            [
                ("REP", "rep_HERO_aalya"),
                ("ewk", "bank_alias"),
                ("REP", "rep_HERO_aalya")
            ]
        );
        assert!(
            loaded.heroes.is_empty(),
            "loading a class does not field a hero"
        );
    }

    #[test]
    fn every_bf2_mission_keeps_all_loaded_classes_before_roster_filtering() {
        if no_missions() {
            return;
        }
        let mut missions = Vec::new();
        for path in std::fs::read_dir(missions_dir()).unwrap() {
            let path = path.unwrap().path();
            if path.extension().is_none_or(|x| x != "ron") {
                continue;
            }
            let m = MissionDef::load(&path).unwrap();
            if m.source_game == "bf2" && m.mode != "ass" {
                missions.push((path, m));
            }
        }
        assert_eq!(missions.len(), 34);
        if missions.iter().all(|(_, m)| m.class_load_order.is_empty()) {
            eprintln!(
                "SKIP: all BF2 missions predate SIDE load-order metadata; regenerate missions"
            );
            return;
        }
        let mut heroes = 0;
        for (path, m) in &missions {
            assert!(
                m.class_load_order.len() > m.heroes.len(),
                "{}: incomplete SIDE load-order metadata",
                path.display()
            );
            for (_, hero) in &m.heroes {
                heroes += 1;
                assert!(
                    m.class_load_order
                        .iter()
                        .any(|load| load.request.eq_ignore_ascii_case(hero)),
                    "{}: missing loaded hero {hero}",
                    path.display()
                );
            }
        }
        assert_eq!(heroes, 66);
        let cw = MissionDef::load(&missions_dir().join("tat2_con_cw.ron")).unwrap();
        let at = |name: &str| {
            cw.class_load_order
                .iter()
                .position(|load| load.request == name)
                .unwrap()
        };
        assert!(at("rep_inf_ep3_rocketeer") < at("rep_inf_ep3_rifleman"));
        assert!(at("rep_hero_obiwan") < at("cis_hero_darthmaul"));
        assert_eq!(cw.class_load_order[at("rep_hero_obiwan")].side, "rep");
        assert_eq!(cw.class_load_order[at("cis_hero_darthmaul")].side, "cis");
    }

    #[test]
    fn local_teams_keep_the_script_team_and_full_roster() {
        let base = r#"(map: "x", mode: "con", source_game: "bf2", teams: [],
            ai_alive_cap: 16, spawn_delay: 10.0, spawn_interval: 0.25,"#;
        let current: MissionDef = ron::from_str(&format!(
            r#"{base} local_teams: [(team: 4, units: 3, classes: [
                ("first", 2, None), ("second", 1, Some(2)),
            ])], local_team_relations: [(4, 1, true), (2, 4, false)])"#
        ))
        .unwrap();
        assert_eq!(
            current.local_teams,
            [LocalTeamDef {
                team: 4,
                units: 3,
                classes: vec![("first".into(), 2, None), ("second".into(), 1, Some(2))],
            }]
        );

        assert_eq!(current.local_team_relations, [(4, 1, true), (2, 4, false)]);

        let legacy: MissionDef =
            ron::from_str(&format!(r#"{base} locals: Some(("first", 3)))"#)).unwrap();
        assert_eq!(legacy.locals, Some(("first".into(), 3)));
        assert!(legacy.local_teams.is_empty());
        assert!(legacy.local_team_relations.is_empty());
    }

    fn cp(name: &str) -> core::cp::CpDef {
        core::cp::CpDef {
            name: name.into(),
            pos: glam::Vec3::ZERO,
            capture: core::region::Region::sphere(glam::Vec3::ZERO, 6.0),
            control: None,
            value_bleed: 10,
            value_atk: [10; 2],
            value_def: [10; 2],
            spawn_nodes: Vec::new(),
            capture_time: 10.0,
            neutralize_time: 12.0,
        }
    }

    /// Card MAIS: the script's AI settings reach the sim - the view
    /// multiplier clamped as BF2 clamps it, Lua team `t` as port team
    /// `t - 1`, a capture ban on its post by name (any case) and team; a
    /// mission that sets none leaves every engine default.
    #[test]
    fn the_missions_ai_settings_reach_the_sim() {
        let ron = r#"(map: "x", mode: "con", source_game: "bf2", teams: [
            (faction: "all", units: 20, tickets: 150), (faction: "imp", units: 20, tickets: 150)],
            ai_alive_cap: 16, spawn_delay: 10.0, spawn_interval: 0.25,
            ai: (view_mult: Some(0.35), aggressiveness: [(1, 1.0), (2, 0.7)],
                 snipe_suitability: Some(30.0), no_capture: [("CP2", 2), ("cp9", 1)]))"#;
        let m: MissionDef = ron::from_str(ron).expect("parses");
        let mut sim = core::sim::Sim::empty(1);
        sim.add_cp(cp("cp1"), None);
        sim.add_cp(cp("cp2"), None);
        assert_eq!(m.apply_ai(&mut sim), 1, "cp9 is no post here");
        let ai = sim.mission_ai;
        assert_eq!(ai.view_mult, 0.35);
        assert_eq!(ai.aggressiveness, [1.0, 0.7]);
        assert_eq!(ai.snipe_suitability, 30.0);
        assert_eq!(sim.cps[0].ai_capture_ban, 0);
        assert!(sim.cps[1].ai_no_capture(1) && !sim.cps[1].ai_no_capture(0));
        // BF2's clamps.
        let mut far = m.clone();
        far.ai.view_mult = Some(3.0);
        far.ai.snipe_suitability = Some(500.0);
        far.apply_ai(&mut sim);
        assert_eq!(sim.mission_ai.view_mult, 1.0);
        assert_eq!(sim.mission_ai.snipe_suitability, 100.0);
        // None set: the defaults, whatever was there.
        let mut none = m.clone();
        none.ai = AiSettings::default();
        none.apply_ai(&mut sim);
        assert_eq!(sim.mission_ai, core::sim::MissionAi::default());
        // The three retained retail Kamino script dumps set the flag to
        // zero. Loading another mission must also restore the default.
        for (map, allow) in [
            ("bf1_kam1", false),
            ("bf2_kam1", false),
            ("bf2_geo1", true),
            ("tat1", true),
        ] {
            none.map = map.into();
            none.apply_ai(&mut sim);
            assert_eq!(sim.mission_ai.allow_blind_jet_jumps, allow, "{map}");
        }
    }

    /// Card MAIS: the shipped missions carry the PS2 scripts' AI settings
    /// (`scripts/gen_missions.py`, from the bytecode): fog on Dagobah and
    /// Felucia, Endor's slower Imperials in both games, the indoor maps'
    /// snipe distance, BF2 Naboo's locals barred from every post.
    #[test]
    fn shipped_missions_carry_their_ai_settings() {
        if no_missions() {
            return;
        }
        let load = |n: &str| MissionDef::load(&missions_dir().join(n)).expect(n);
        for (n, v) in [
            ("bf2_dag1_con.ron", 0.35),
            ("bf2_dag1_con_cw.ron", 0.35),
            ("bf2_fel1_con.ron", 0.65),
            ("bf2_fel1_con_cw.ron", 0.65),
        ] {
            assert_eq!(load(n).ai.view_mult, Some(v), "{n}");
        }
        assert_eq!(
            load("bf2_end1_con.ron").ai.aggressiveness,
            [(1, 1.0), (2, 0.7)]
        );
        assert_eq!(
            load("bf1_end1_con.ron").ai.aggressiveness,
            [(1, 1.0), (2, 0.7)]
        );
        for n in [
            "bf2_cor1_con.ron",
            "bf2_tan1_con_cw.ron",
            "bf2_tat3_con.ron",
        ] {
            assert_eq!(load(n).ai.snipe_suitability, Some(30.0), "{n}");
        }
        let nab = load("bf2_nab2_con.ron").ai.no_capture;
        assert_eq!(nab.len(), 6);
        assert!(nab.iter().all(|(_, t)| *t == 3));
        assert_eq!(load("bf2_kas2_con.ron").ai, AiSettings::default());
    }

    /// The two original v0 missions still carry the RE'd numbers after the
    /// generator took them over. Both files changed identity slightly:
    /// `tat1_con.ron` is now BF1 `tat1i` (the GCW era of Dune Sea; the CW
    /// era is `tat1_con_cw.ron`) and its teams are in MISSION-team order, so
    /// team 1 is the attacking Empire, not the Alliance. `tat2_con.ron` is
    /// likewise BF2 `tat2g_con`, with `tat2_con_cw.ron` holding the
    /// `tat2c_con` numbers re-tickets-spawn.md §1.5–1.6 quotes.
    #[test]
    fn shipped_missions_parse() {
        if no_missions() {
            return;
        }
        let dir = missions_dir();
        let t1 = MissionDef::load(&dir.join("tat1_con.ron")).expect("tat1_con");
        assert_eq!((t1.map.as_str(), t1.source_game.as_str()), ("tat1", "bf1"));
        assert_eq!(t1.era.as_deref(), Some("gcw"));
        assert_eq!(t1.factions(), ["imp".to_string(), "all".to_string()]);
        assert_eq!(t1.tickets(), [250, 250]);
        assert_eq!(t1.ai_alive_cap, 25, "BF1 has no cap below the member pool");
        assert_eq!(t1.initial_ai(0, true), 24);
        assert_eq!(t1.initial_ai(1, false), 25);
        assert_eq!(t1.death_regions, ["Sarlac01"]);
        assert_eq!(t1.attacking_team, Some(1));

        let cw = MissionDef::load(&dir.join("tat1_con_cw.ron")).expect("tat1_con_cw");
        assert_eq!(cw.factions(), ["rep".to_string(), "cis".to_string()]);
        assert_eq!(cw.tickets(), [250, 250]);

        let t2 = MissionDef::load(&dir.join("tat2_con.ron")).expect("tat2_con");
        assert_eq!(t2.tickets(), [150, 150]);
        assert_eq!(t2.ai_alive_cap, 16);
        assert_eq!(t2.initial_ai(0, true), 16, "capped by NumBots");
        assert_eq!(t2.spawn_delay, 10.0);
        let t2cw = MissionDef::load(&dir.join("tat2_con_cw.ron")).expect("tat2_con_cw");
        assert_eq!(t2cw.factions(), ["rep".to_string(), "cis".to_string()]);
        assert_eq!(
            (t2cw.teams[0].units, t2cw.tickets()[0], t2cw.ai_alive_cap),
            (20, 150, 16),
            "tat2c_con, the mission re-tickets-spawn.md §1.6 works its \
             reference vectors from"
        );
    }

    /// The per-team class MIX reaches the RON in the script's own order, with
    /// the counts the bytecode carries (D1): BF1 `AddUnitClass` (count, no
    /// max), BF2 `SetupTeams` slots (min and max).
    #[test]
    fn team_class_mixes_come_through_in_mission_order() {
        if no_missions() {
            return;
        }
        let dir = missions_dir();
        let t1 = MissionDef::load(&dir.join("tat1_con.ron")).expect("tat1_con");
        // tat1i: team 2 is the Alliance, five AddUnitClass calls in order.
        assert_eq!(t1.factions()[1], "all");
        assert_eq!(
            t1.teams[1].classes,
            vec![
                ("all_inf_soldierdesert".to_string(), 11, None),
                ("all_inf_vanguard".to_string(), 3, None),
                ("all_inf_pilot".to_string(), 4, None),
                ("all_inf_marksman".to_string(), 4, None),
                ("all_inf_smuggler".to_string(), 1, None),
            ]
        );
        // The counts are MINIMUMS: 23 of a member pool of 25.
        assert_eq!(t1.teams[1].classes.iter().map(|c| c.1).sum::<u32>(), 23);
        assert_eq!(t1.teams[1].units, 25);
        assert_eq!(t1.teams[0].classes.len(), 5, "the Empire's five");

        // kam1c_con: SetupTeams slot order with min AND max.
        let k = MissionDef::load(&dir.join("bf2_kam1_con_cw.ron")).expect("kam1_con_cw");
        assert_eq!(k.factions()[1], "rep");
        assert_eq!(
            k.teams[1].classes,
            vec![
                ("rep_inf_ep3_rifleman".to_string(), 9, Some(25)),
                ("rep_inf_ep3_rocketeer".to_string(), 1, Some(4)),
                ("rep_inf_ep3_engineer".to_string(), 1, Some(4)),
                ("rep_inf_ep3_sniper".to_string(), 1, Some(4)),
                ("rep_inf_ep3_officer".to_string(), 1, Some(4)),
                ("rep_inf_ep3_jettrooper".to_string(), 1, Some(4)),
            ]
        );
        assert_eq!(k.teams[1].classes.iter().map(|c| c.1).sum::<u32>(), 14);
        assert_eq!(k.teams[1].units, 20);
        // The bytecode spells the CIS classes "CIS_inf_rifleman"; the
        // generator lowercases on the way out.
        assert_eq!(k.teams[0].classes[0].0, "cis_inf_rifleman");
        assert_eq!(k.teams[0].classes[5].0, "cis_inf_droideka");
    }

    /// Card ERAM, acceptance 1: over every map and every ordered pair of the
    /// four armies, a pair that is one of the map's missions' own (either
    /// order) loads that mission with the first army on its own team there;
    /// any other pair loads the map's default mission with the player on
    /// team 0, as before the card.
    #[test]
    fn the_mission_whose_pair_was_picked_is_loaded() {
        if no_missions() {
            return;
        }
        const ARMIES: [&str; 4] = ["all", "imp", "rep", "cis"];
        let mut maps: Vec<String> = std::fs::read_dir(missions_dir())
            .unwrap()
            .filter_map(|e| {
                let n = e.unwrap().file_name().to_string_lossy().into_owned();
                n.strip_suffix("_con.ron").map(str::to_owned)
            })
            .collect();
        maps.sort();
        let mut mission_count = maps.len();
        let (mut cw, mut gcw, mut cross, mut seat1) = (0, 0, 0, 0);
        for map in &maps {
            let default = MissionDef::load(&missions_dir().join(format!("{map}_con.ron"))).unwrap();
            let other = MissionDef::load(&missions_dir().join(format!("{map}_con_cw.ron"))).ok();
            mission_count += usize::from(other.is_some());
            for a in ARMIES {
                for b in ARMIES {
                    let p = pick(missions_dir(), map, "con", [a, b]).unwrap();
                    let name = p.path.file_name().unwrap().to_string_lossy().into_owned();
                    let own = [Some(&default), other.as_ref()]
                        .into_iter()
                        .flatten()
                        .find(|m| {
                            let f = m.factions();
                            a != b && [a, b].iter().all(|x| f.iter().any(|y| y == x))
                        });
                    match own {
                        Some(m) => {
                            assert!(p.own, "{map} {a} v {b}");
                            assert_eq!(p.mission.factions(), m.factions(), "{map} {a} v {b}");
                            assert_eq!(p.mission.era, m.era, "{map} {a} v {b}");
                            // The player's army is on its own team.
                            assert_eq!(
                                p.mission.teams[usize::from(p.player_team)].faction,
                                a,
                                "{map} {a} v {b}"
                            );
                            seat1 += usize::from(p.player_team == 1);
                            if name.ends_with("_con_cw.ron") {
                                cw += 1;
                            } else {
                                gcw += 1;
                            }
                        }
                        None => {
                            assert!(!p.own, "{map} {a} v {b}");
                            assert_eq!(name, format!("{map}_con.ron"));
                            assert_eq!(p.player_team, 0);
                            cross += 1;
                        }
                    }
                }
            }
        }
        println!(
            "ERAM pick: {} maps x 16 pairs: {cw} load _con_cw.ron, {gcw} the default as its own \
             pair, {cross} the default as a cross-era pair; player on team 1 in {seat1}",
            maps.len()
        );
        assert_eq!(cw, (mission_count - maps.len()) * 2);
        assert_eq!(gcw, maps.len() * 2);
        assert_eq!(cw + gcw + cross, maps.len() * 16);
        assert_eq!(seat1, mission_count);
        assert!(pick(missions_dir(), "bf1_nomap", "con", ["all", "imp"]).is_none());
    }

    /// Every mission RON in the directory parses, names a plausible map/era,
    /// and passes `load`'s validation. This is the referee for the generator:
    /// a malformed emit fails here rather than at map-load time.
    #[test]
    fn every_mission_ron_parses() {
        if no_missions() {
            return;
        }
        let dir = missions_dir();
        let mut files: Vec<_> = std::fs::read_dir(dir)
            .expect("missions dir")
            .map(|e| e.expect("dir entry").path())
            .filter(|p| p.extension().is_some_and(|e| e == "ron"))
            .collect();
        files.sort();
        assert!(files.len() >= 32, "expected a mission per baked map");
        for p in &files {
            let m = MissionDef::load(p).unwrap_or_else(|e| panic!("{e:#}"));
            let stem = p.file_stem().unwrap().to_str().unwrap();
            if m.mode != "con" {
                assert_eq!(stem, format!("{}_{}", m.map, m.mode));
                continue;
            }
            // `_con_cw` always means the clone wars; the reverse does not
            // hold, because a map that ships ONLY a clone-wars mission (BF1
            // Geonosis and Kamino, BF2 Geonosis) is its map's `_con.ron`.
            if stem.ends_with("_con_cw") {
                assert_eq!(
                    m.era.as_deref(),
                    Some("cw"),
                    "{stem}: `_con_cw` file is not the clone-wars era"
                );
                assert!(
                    dir.join(format!("{}_con.ron", m.map)).exists(),
                    "{stem}: a `_con_cw` file with no GCW twin"
                );
            }
            assert!(
                matches!(m.era.as_deref(), Some("cw") | Some("gcw")),
                "{stem}: era must be cw or gcw"
            );
            let mode = &m.mode;
            assert!(
                stem.starts_with(&m.map) && stem[m.map.len()..].starts_with(&format!("_{mode}")),
                "{stem}: file name does not match map {:?}/mode {:?}",
                m.map,
                m.mode
            );
            for t in &m.teams {
                assert!(
                    ["all", "imp", "rep", "cis"].contains(&t.faction.as_str()),
                    "{stem}: unknown faction {:?}",
                    t.faction
                );
                assert!(t.units > 0, "{stem}: empty member pool");
                // Every conquest mission names a class mix; the counts are
                // minimums, so they never EXCEED the member pool, and a max
                // is never below its own min.
                assert!(
                    !t.classes.is_empty(),
                    "{stem}: {} has no classes",
                    t.faction
                );
                for (c, min, max) in &t.classes {
                    assert!(!c.is_empty() && c == &c.to_lowercase(), "{stem}: {c:?}");
                    if let Some(m) = max {
                        assert!(m >= min, "{stem}: {c} max {m} < min {min}");
                    }
                }
                assert!(
                    t.classes.iter().map(|c| c.1).sum::<u32>() <= t.units,
                    "{stem}: {} class minimums exceed the member pool",
                    t.faction
                );
            }
            assert!(m.ai_alive_cap > 0 && m.spawn_interval > 0.0);
            for (cp, team) in &m.cps {
                assert!(!cp.is_empty() && *team <= 2, "{stem}: bad cp {cp:?}");
            }
            // BF2 conquest is an ObjectiveConquest fed an explicit roster, so
            // every BF2 mission names its posts; BF1 inlines the mode and
            // names none. (That the names are real is covered by the
            // generator's check that every string it emits appears in the
            // script's own PS2 constant table.)
            if m.is_hero_assault() {
                assert!(
                    m.posts.is_empty(),
                    "{stem}: an objective with no post roster"
                );
            } else if m.source_game == "bf2" {
                assert!(!m.posts.is_empty(), "{stem}: no command-post roster");
                for cp in &m.posts {
                    assert!(!cp.is_empty(), "{stem}: empty post name");
                }
            } else {
                assert!(
                    m.posts.is_empty(),
                    "{stem}: BF1 hands no roster to an objective"
                );
            }
            // A `--ps2-only` mission (scripts/pack.py) has no PC referee.
            assert!(m.source.contains("PS2 "), "{stem}: no provenance");
        }
        println!("{} mission RONs parsed", files.len());
    }

    /// The two eras of a map never collapse onto the same file, and a map
    /// with both eras really does field different sides in each.
    #[test]
    fn eras_are_distinct() {
        if no_missions() {
            return;
        }
        let dir = missions_dir();
        for key in ["tat1", "tat2", "bf1_kas2", "bf2_kam1"] {
            let g = MissionDef::load(&dir.join(format!("{key}_con.ron"))).expect(key);
            let c = MissionDef::load(&dir.join(format!("{key}_con_cw.ron"))).expect(key);
            let gcw: Vec<_> = g.factions().to_vec();
            assert!(
                gcw.iter().all(|f| f == "all" || f == "imp"),
                "{key}: `_con.ron` should be the GCW era, got {gcw:?}"
            );
            let cw: Vec<_> = c.factions().to_vec();
            assert!(
                cw.iter().all(|f| f == "rep" || f == "cis"),
                "{key}: `_con_cw.ron` should be the clone wars, got {cw:?}"
            );
        }
    }

    /// PLAN Log "Cleanse" CORRECTION 2: BF2 Hoth ends in 20 s because every
    /// `hoth_cps` control zone authors one team in the world and only the
    /// mission Lua splits them. The mission data has to be able to say so.
    #[test]
    fn bf2_hoth_reassigns_command_posts() {
        if no_missions() {
            return;
        }
        let m = MissionDef::load(&missions_dir().join("bf2_hot1_con.ron")).expect("hot1");
        assert_eq!(
            m.cps,
            vec![("CP3".to_string(), 1), ("CP6".to_string(), 1)],
            "hot1g_con does SetObjectTeam(\"CP3\", 1) / SetObjectTeam(\"CP6\", 1)"
        );
        // The round is four posts, not five: CP7 is killed outright and the
        // objective is built from CP3..CP6 only, so 2-2 at tick 1.
        assert_eq!(m.posts, ["CP3", "CP4", "CP5", "CP6"]);
        assert_eq!(m.killed, ["CP7"]);
        assert_eq!(m.factions(), ["imp".to_string(), "all".to_string()]);
    }

    /// DSD: only the two Death Star RONs carry a death drain — Lua team 1's
    /// own deaths cost it a second ticket — and it reaches the battle.
    #[test]
    fn only_the_death_star_drains_a_second_ticket() {
        if no_missions() {
            return;
        }
        let mut with = Vec::new();
        for e in std::fs::read_dir(missions_dir()).expect("missions dir") {
            let p = e.expect("entry").path();
            if p.extension().and_then(|x| x.to_str()) != Some("ron") {
                continue;
            }
            let m = MissionDef::load(&p).expect("mission parses");
            if !m.death_drains.is_empty() {
                assert_eq!(
                    m.death_drains,
                    [DeathDrain {
                        on: 0,
                        team: 0,
                        tickets: 1
                    }],
                    "{}",
                    p.display()
                );
                with.push(p.file_name().unwrap().to_string_lossy().into_owned());
            }
        }
        with.sort();
        assert_eq!(with, ["bf2_dea1_con.ron", "bf2_dea1_con_cw.ron"]);

        let m = MissionDef::load(&missions_dir().join("bf2_dea1_con.ron")).expect("dea1");
        let mut b = core::battle::Battle::new(m.tickets());
        m.apply_death_drains(&mut b);
        assert_eq!(b.death_drain, [[1, 0], [0, 0]]);
    }

    /// Card SSELB acceptance 1: the mission RON carries the script's
    /// `AddCameraShot` list - hot1g_con's three, the first as the script
    /// writes it - and every mission on both discs has 3 to 16.
    #[test]
    fn missions_carry_their_camera_shots() {
        if no_missions() {
            return;
        }
        let m = MissionDef::load(&missions_dir().join("bf2_hot1_con.ron")).expect("hot1");
        assert_eq!(m.camera_shot_calls.len(), 3);
        assert_eq!(
            m.camera_shot_calls[0],
            [0.94421, 0.065541, 0.321983, -0.02235, -500.48984, 0.797472, -68.77385]
        );
        let mut n = 0;
        for e in std::fs::read_dir(missions_dir()).expect("missions dir") {
            let p = e.expect("entry").path();
            if p.extension().is_none_or(|x| x != "ron") {
                continue;
            }
            let m = MissionDef::load(&p).expect("parse");
            let k = m.camera_shot_calls.len();
            let least = if m.mode == "ass" { 1 } else { 3 };
            assert!((least..=16).contains(&k), "{}: {k} shots", p.display());
            n += 1;
        }
        assert!(n >= 57, "{n} missions read");
    }

    /// Card SSELB acceptance 2: the port's view at the side select on Hoth
    /// is shot 0 and stands where the PS2's camera stood
    /// (`engine/artifacts/lead_tmp/ssel/t1_hot1/s0_team1.p2s`, read by
    /// `lead_tmp/sselb/pose.py`: eye (-500.4898, 0.7975, -68.7738), back row
    /// (0.6051, -0.1382, 0.7841), tan_v 0.34131), within 0.05 m and 0.1 deg.
    #[test]
    fn hoth_side_select_stands_at_the_ps2_eye() {
        if no_missions() {
            return;
        }
        let m = MissionDef::load(&missions_dir().join("bf2_hot1_con.ron")).expect("hot1");
        let mut b = crate::spawn_backdrop::Backdrop::new(m.camera_shots(), 1).expect("shots");
        b.follow(core::sim::SpawnStage::Side);
        let c = b.camera();
        let eye = glam::Vec3::new(-500.4898, 0.7975, -68.7738);
        assert!(c.position.distance(eye) < 0.05, "{:?}", c.position);
        let ps2_fwd = -glam::Vec3::new(0.6051, -0.1382, 0.7841).normalize();
        let deg = c
            .forward()
            .dot(ps2_fwd)
            .clamp(-1.0, 1.0)
            .acos()
            .to_degrees();
        assert!(deg < 0.1, "view {deg} deg off the PS2's");
        assert!(((c.fov_y * 0.5).tan() - 0.34131).abs() < 1e-5);
    }
}
